#!/usr/bin/env python3
"""Build the lab's plain HTML pages. No third-party dependencies required."""
from pathlib import Path
from html import escape as E
import json
from datetime import date

ROOT = Path(__file__).resolve().parent
FACULTY='https://soils.ifas.ufl.edu/people/faculty/marcio-nunes/'
SCHOLAR='https://scholar.google.com/citations?user=fVVsZKgAAAAJ&hl=en'
ORCID='https://orcid.org/0000-0002-3674-279X'
FEATURE='https://blogs.ifas.ufl.edu/swsdept/2022/08/27/featured-new-faculty-marcio-nunes-assistant-professor-of-tropical-soils/'
APP='https://gshape-web.streamlit.app/'

ICONS={
 'leaf':'<path d="M20 4C9 2 3 8 6 15c5 7 15 1 14-11Z"/><path d="M4 21 16 9M10 15v-5M10 15h5"/>',
 'book':'<path d="M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3Z"/><path d="M12 6v16M6 8h3M15 8h3M6 12h3M15 12h3"/>',
 'layers':'<path d="m3 7 9-5 9 5-9 5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',
 'flask':'<path d="M9 2h6M10 2v7L4 19q-1 3 2 3h12q3 0 2-3L14 9V2M7 15h10"/>',
 'grid':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 'people':'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 3a4 4 0 0 1 0 8M19 15a5 5 0 0 1 3 6"/>',
 'pin':'<path d="M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 0 1 16 0Z"/><circle cx="12" cy="9" r="2.5"/>',
 'news':'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 7h10M7 11h4M7 15h4M14 11h3M14 15h3"/>',
 'award':'<circle cx="12" cy="8" r="6"/><path d="m8 13-2 9 6-3 6 3-2-9"/>',
 'globe':'<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2c-7 7-7 13 0 20 7-7 7-13 0-20Z"/>',
 'waves':'<path d="M2 7q3-4 6 0t6 0 6 0M2 12q3-4 6 0t6 0 6 0M2 17q3-4 6 0t6 0 6 0"/>',
}
def icon(name):
 return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS.get(name,ICONS['leaf'])+'</svg>'
def arrow(text,url,cls='link-arrow'):
 return f'<a class="{cls}" href="{E(url,quote=True)}">{E(text)} <span aria-hidden="true">&#8599;</span></a>'
def navlink(name,url,current):
 return f'<a href="{url}"'+(' aria-current="page"' if current==url else '')+f'>{name}</a>'
def header(current):
 about=[('Overview','about.html'),('Biography','biography.html'),('Team','team.html'),('Media','media.html'),('News','news.html')]
 research=[('Projects','projects.html'),('Publications','publications.html'),('Soil Health Data','soil-health-data.html'),('Tools','tools.html')]
 def drop(name,links):
  return '<details><summary>'+name+'</summary><div class="dropdown">'+''.join(navlink(t,u,current) for t,u in links)+'</div></details>'
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><nav class="wrap nav" aria-label="Main navigation"><a class="wordmark" href="index.html"><span class="brand-icon">{icon('leaf')}</span><span><strong>Sustainable Tropical<br>Soil Management Lab</strong><small>UNIVERSITY OF FLORIDA · UF/IFAS</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-navigation">Menu</button><div class="nav-items" id="site-navigation">{navlink('Home','index.html',current)}{drop('About',about)}{drop('Research',research)}{navlink('Teaching &amp; Extension','teaching-extension.html',current)}{navlink('Opportunities','opportunities.html',current)}{navlink('Contact','contact.html',current)}</div></nav></header>'''
def footer():
 return f'''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><strong>Sustainable Tropical Soil Management Lab</strong><p>Directed by Dr. Márcio R. Nunes<br>University of Florida · UF/IFAS</p></div><div><strong>Find us</strong><p>Soil, Water, and Ecosystem Sciences<br>Gainesville, Florida, USA</p></div><div><strong>Explore</strong><div class="footer-links"><a href="biography.html">Our director</a><a href="team.html">Team</a><a href="tools.html">Tools</a><a href="news.html">News</a><a href="contact.html">Contact</a></div></div></div><div class="footer-bottom"><span>© 2026 Sustainable Tropical Soil Management Lab</span><div class="footer-links"><a href="https://accessibility.ufl.edu/">Accessibility</a><a href="https://privacy.ufl.edu/">Privacy</a><a href="credits.html">Image &amp; content credits</a></div></div></div></footer>'''
def page(file,title,body,section='',desc=''):
 fulltitle=title+' | Sustainable Tropical Soil Management Lab'
 text=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(desc or title+' — Sustainable Tropical Soil Management Lab, UF/IFAS.',quote=True)}"><meta name="theme-color" content="#224e40"><title>{E(fulltitle)}</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head><body>{header(file)}<main id="main">{body}</main>{footer()}</body></html>'''
 (ROOT/file).write_text(text,encoding='utf-8')
def head(title,desc,category,crumb=''):
 return f'<div class="page-head"><div class="wrap"><p class="crumb"><a href="index.html">Home</a><span>/</span>{E(crumb or category)}</p><p class="eyebrow">{E(category)}</p><h1>{title}</h1><p class="lead">{desc}</p></div></div>'
def tile(title,desc,url,label='Explore',symbol='leaf'):
 return f'<article class="tile"><div class="icon-box">{icon(symbol)}</div><h3>{title}</h3><p>{desc}</p>{arrow(label,url)}</article>'
def contact_strip():
 return '''<section><div class="wrap contact-strip"><div><p class="eyebrow">Get in touch</p><h2>Let’s Talk Soil.</h2><p>Have a research question or an idea for collaboration?<br>Connect with Dr. Márcio R. Nunes.</p>'''+arrow('marcionunes@ufl.edu','mailto:marcionunes@ufl.edu')+'''</div><div class="contact-details"><p><strong>Sustainable Tropical Soil Management Lab</strong><br>Department of Soil, Water, and Ecosystem Sciences<br>University of Florida · UF/IFAS</p><p>G169 McCarty Hall A<br>2181 McCarty Hall, PO Box 110290<br>Gainesville, FL 32611</p><a href="contact.html">Contact &amp; location details</a></div></div></section>'''
def app_window():
 return '<div class="tool-window"><div class="window-top" aria-hidden="true"><i></i><i></i><i></i></div><img src="assets/gshape-interface.jpg" alt="gSHAPE interface with location, evaluation framework, and soil indicator selections" width="1350" height="900" loading="lazy"></div>'
NEWS=json.loads((ROOT/'news-content.json').read_text())
def date_label(value):
 return date.fromisoformat(value).strftime('%b %d, %Y').replace(' 0',' ')
def news_card(item):
 typ='publication' if item['category']=='Publications' else ('tool' if item['category']=='Tools' else 'media' if item['category']=='Media' else '')
 art=icon('book' if typ=='publication' else 'grid' if typ=='tool' else 'news')
 url='news-'+item['slug']+'.html'
 return f'<article class="news-card" data-category="{item["category"]}"><div class="news-art {typ}">{art}</div><div class="news-body"><div class="meta"><span class="badge">{item["category"]}</span><time datetime="{item["date"]}">{date_label(item["date"])}</time></div><h3><a href="{url}">{E(item["title"])}</a></h3><p>{E(item["summary"])}</p>{arrow("Read article",url)}</div></article>'
def feed(filters=False):
 buttons=''
 if filters:buttons='<div class="filters" aria-label="Filter news">'+''.join(f'<button type="button" data-category-filter="{t}" aria-pressed="{str(t=="All").lower()}">{t}</button>' for t in ['All','Lab updates','Publications','Tools','Media'])+'</div>'
 return '<div data-news-feed data-page-size="3">'+buttons+'<div class="news-grid">'+''.join(news_card(n) for n in NEWS)+'</div><p class="empty-state" data-empty hidden>No announcements in this category yet.</p><div class="pager"><button type="button" data-previous aria-label="Previous news page">← Previous</button><p role="status" aria-live="polite" data-page-status></p><button type="button" data-next aria-label="Next news page">Next →</button></div><noscript><p>All news articles are shown above. Enable JavaScript for pagination and category filters.</p></noscript></div>'

home='''<section class="hero"><img class="hero-photo" src="assets/fields.jpg" width="2000" height="1333" alt="Aerial view of a green agricultural field" fetchpriority="high"><div class="wrap"><p class="eyebrow">Science rooted in the tropics</p><h1>Healthy soils.<br><em>A sustainable future.</em></h1><p class="lead">Understanding tropical soils to support productive agriculture, healthy ecosystems, and better lives.</p><div class="actions">'''+arrow('Discover our research','projects.html','button light')+arrow('Meet our director','biography.html')+'''</div></div><span class="hero-note">AGRICULTURAL LANDSCAPE · PHOTO: DANIEL BOBERG / UNSPLASH</span></section><div class="subline"><div class="wrap"><span>SOIL HEALTH</span><span>SUSTAINABLE AGRICULTURE</span><span>RESEARCH · TEACHING · EXTENSION</span></div></div><section><div class="wrap intro-grid"><div><p class="eyebrow">Our mission</p><h2>Better decisions<br>begin beneath our feet.</h2></div><div><p>We connect soil processes with practical management to help sustain food production and protect natural resources in tropical agricultural systems.</p><p class="director-line">Led by <a href="biography.html">Dr. Márcio R. Nunes</a><br>Director of the Sustainable Tropical Soil Management Laboratory</p></div></div></section><section class="dark"><div class="wrap tool-feature"><div><p class="eyebrow">Tools &amp; innovations</p><h2>Soil health.<br>In context. Online.</h2><p>Meet gSHAPE, our web tool for context-specific soil health assessment and benchmarking.</p><div class="actions">'''+arrow('Explore gSHAPE','gshape.html','button light')+arrow('Open the app',APP,'button white')+'''</div></div>'''+app_window()+'''</div></section><section class="soft"><div class="wrap"><div class="section-head"><div><p class="eyebrow">From the lab</p><h2>Latest News</h2></div>'''+arrow('All news &amp; updates'.replace('&amp;','&'),'news.html')+'''</div>'''+feed()+'''</div></section>'''+contact_strip()
page('index.html','Home',home,desc='Sustainable Tropical Soil Management Lab at the University of Florida: research, teaching, and tools for healthier tropical soils.')

about=head('Science with roots.<br>Research with purpose.','Meet the people and ideas behind our work in tropical soil management.','About')+'<section><div class="wrap intro-grid"><div><p class="eyebrow">Our laboratory</p><h2>Soils connect agriculture,<br>ecosystems, and people.</h2></div><div><p>At the University of Florida, our laboratory brings soil science into the decisions that shape agricultural systems. Our focus spans soil health assessment, sustainable management, and practical digital tools.</p><p>Dr. Márcio R. Nunes directs the laboratory within the Department of Soil, Water, and Ecosystem Sciences, UF/IFAS.</p></div></div></section><section class="soft"><div class="wrap tiles">'+tile('Our director','Meet Dr. Márcio R. Nunes and explore his research, education, and academic experience.','biography.html','Read biography','people')+tile('Our team','Meet our lab manager, postdoctoral researchers, graduate students, and visiting colleagues.','team.html','Meet the team','globe')+tile('Media & News','Explore lab announcements, research publications, and stories about our work.','news.html','Read the latest','news')+'</div></section>'
page('about.html','About',about)

bio=head('Márcio R. Nunes','Director of the Sustainable Tropical Soil Management Laboratory · Assistant Professor of Tropical Soils, UF/IFAS.','About / Biography')+f'''<section><div class="wrap bio-hero"><div class="bio-photo"><img src="assets/marcio-nunes.jpg" width="280" height="350" alt="Professor Márcio R. Nunes"></div><div><p class="eyebrow">Lab director</p><h2>From a family farm<br>to soil science.</h2><p class="title">Research · Teaching · Soil health</p><p>Raised on a farm in southern Brazil, Márcio brings agricultural experience to research on soil management in tropical and temperate environments. His work connects soil health assessment with agricultural productivity and natural resource stewardship.</p><div class="profile-links"><a href="{SCHOLAR}">Google Scholar ↗</a><a href="{ORCID}">ORCID ↗</a><a href="{FACULTY}">UF faculty profile ↗</a></div></div></div></section><section class="soft"><div class="wrap bio-layout"><div><p class="eyebrow">Career</p><h2>Employment Experience</h2><div class="timeline"><article><span class="date">2022 – PRESENT</span><h3>University of Florida</h3><p>Assistant Professor of Tropical Soils.<br>Department of Soil, Water, and Ecosystem Sciences.</p></article><article><span class="date">PRIOR TO UF · FOUR YEARS</span><h3>USDA Agricultural Research Service</h3><p>Research on soil health and management.</p></article></div><h2>Academic Experience</h2><p>Doctoral research at Cornell University during 2017–2018, followed by research and teaching at UF.</p>{arrow('Explore teaching & extension','teaching-extension.html')}</div><div><p class="eyebrow">Education</p><h2>Education</h2><div class="timeline"><article><h3>Ph.D. · Soils and Plant Nutrition</h3><p>University of São Paulo, Brazil.</p></article><article><h3>M.S. · Soils and Water Management</h3><p>Federal University of Pelotas, Brazil.</p></article><article><span class="date">2012</span><h3>B.S. · Agronomy</h3><p>Federal University of Pelotas, Brazil.</p></article></div><p class="source-note">Career and education: <a href="{FEATURE}">UF/IFAS faculty feature</a>.</p></div></div></section><section><div class="wrap bio-layout"><div><div class="icon-box">{icon('award')}</div><h2>Professional Achievements</h2><p>His research portfolio includes the development of SHAPE soil health scoring and benchmarking approaches, with applications to soil organic carbon and other dynamic indicators.</p>{arrow('Selected research publications','publications.html')}</div><div><div class="icon-box">{icon('book')}</div><h2>Editorial Activities</h2><div class="notice"><p>A detailed list of editorial appointments and professional service will be added from the director’s updated CV.</p></div></div></div></section>'''
page('biography.html','Biography — Márcio R. Nunes',bio)

groups=[('Director',['Márcio R. Nunes']),('Lab Manager',['Diego Arruda Huggins De Sa Leitao']),('Postdoctoral Researchers',['Camila P. Cagna','Pedro Antônio Namorato Benevenute']),('Graduate Students',['Mohkam Singh','Moges Kidane Biru','Olanrewaju H. Ologunde','Renan Pedro Becker','Glauco Mariano Teixeira Junior','Labake O. Agunbiade']),('Visiting Scholars',['João Pedro Balbinot Meoti','Antonio Azevedo Batista']),('Visiting Professor',['Luiz Roberto Guimarães Guilher'])]
team=head('Our team','The people behind our research, teaching, and collaboration.','About / Team')+'<section><div class="wrap">'
for group,names in groups:
 team+=f'<div class="team-group"><div class="group-head"><h2>{group}</h2><span class="count">{len(names)}</span></div><div class="team-grid">'
 for name in names:
  if group=='Director':team+=f'<article class="member director"><img src="assets/marcio-nunes.jpg" alt="Dr. Márcio R. Nunes" width="140" height="160"><div><p class="eyebrow">Laboratory leadership</p><h3>Dr. Márcio R. Nunes</h3><p>Director of the Sustainable Tropical Soil Management Laboratory<br>Assistant Professor of Tropical Soils · UF/IFAS</p>{arrow("Biography & research", "biography.html")}</div></article>'
  else:
   initials=''.join(x[0] for x in name.split()[:2])
   role={'Lab Manager':'Lab Manager','Postdoctoral Researchers':'Postdoctoral Researcher','Graduate Students':'Graduate Student','Visiting Scholars':'Visiting Scholar','Visiting Professor':'Visiting Professor'}[group]
   team+=f'<article class="member"><div class="avatar" aria-hidden="true">{initials}</div><h3>{E(name)}</h3><p class="role">{role}</p></article>'
 team+='</div></div>'
team+='<p class="source-note">Individual photos, research interests, projects, and contact profiles will be added as they become available.</p></div></section>'
page('team.html','Team',team)

projects=head('Research for healthier soils.','Explore our developing project portfolio in soil health and sustainable tropical agriculture.','Research / Projects')+'<section><div class="wrap"><div class="notice"><p><strong>Project outlines</strong> · These are placeholders for the lab’s project descriptions. Collaborators, duration, funding, and impact will be added with the project details.</p></div></div></section><section class="soft"><div class="wrap tiles">'
for i,(title,desc) in enumerate([('Context-aware soil health','A placeholder for research on interpreting soil health indicators in relation to soil properties, climate, and land use.'),('Sustainable soil management','A placeholder for research on agricultural practices, soil functions, and long-term soil stewardship.'),('Digital tools and soil information','A placeholder for research on soil observations, mapping, and decision-support resources.')],1):
 projects+=f'<article class="tile"><span class="project-number">0{i}</span><span class="pill">Project outline · placeholder</span><h3>Project {i}</h3><p><strong>{title}</strong></p><p>{desc}</p><div class="detail-list"><p>Collaborators &amp; duration: to be added</p><p>Funding &amp; impact: to be added</p></div></article>'
projects+='</div></section>'
page('projects.html','Research Projects',projects)

publications=[('2026','A region-specific soil health assessment protocol and evaluation for Sub-Saharan Africa','Biru, M. K., Nunes, M. R., et al.','Communications Earth & Environment','10.1038/s43247-026-03727-1'),('2025','Transferability of soil management assessment framework indices to detect best soil management strategies in tropical agroecosystems','Amorim, H. C. S., Ashworth, A. J., Drescher, G. L., Singh, M., & Nunes, M. R.','Agricultural & Environmental Letters','10.1002/ael2.70013'),('2024','SHAPEv1.0 Scoring curves and peer group benchmarks for dynamic soil health indicators','Nunes, M. R., et al.','Soil Science Society of America Journal','10.1002/saj2.20668'),('2021','The soil health assessment protocol and evaluation applied to soil organic carbon','Nunes, M. R., et al.','Soil Science Society of America Journal','10.1002/saj2.20244')]
pub=head('Selected publications','Research from the lab and Dr. Márcio R. Nunes’s wider research portfolio.','Research / Publications')+'<section><div class="wrap"><div class="section-head"><p>This selected list links to the original publications. For the full portfolio, visit the director’s scholarly profile.</p>'+arrow('Google Scholar',SCHOLAR)+'</div><div class="publication-list">'
for year,title,authors,journal,doi in publications:
 pub+=f'<article class="publication-row"><span class="year">{year}</span><div><h2>{E(title)}</h2><p>{E(authors)}</p><p><em>{E(journal)}</em></p></div>{arrow("Read paper", "https://doi.org/"+doi)}</article>'
pub+='</div></div></section>'
page('publications.html','Publications',pub)

soil=head('Soil Health Data','A developing home for data resources, indicator information, and soil health guidance.','Research / Soil Health Data')+'<section><div class="wrap tiles">'+tile('Soil indicators','An introduction to physical, chemical, and biological indicators used to assess soil condition.','gshape.html','Explore indicators','layers')+tile('Assessment frameworks','Learn how the lab’s web tool brings soil health evaluation frameworks into a common interface.','gshape.html','Explore gSHAPE','grid')+'<article class="tile"><div class="icon-box">'+icon('globe')+'</div><span class="pill">Resource collection · coming soon</span><h3>Data resources</h3><p>Published datasets, accompanying documentation, download links, and reuse conditions will be listed here as they become available.</p></article></div></section><section class="soft"><div class="wrap"><div class="notice"><p>This section currently provides resource placeholders. No research dataset is available for download from this page yet.</p></div></div></section>'
page('soil-health-data.html','Soil Health Data',soil)

teaching=head('Teaching &amp; Extension','Connecting soil science, agricultural management, and hands-on learning.','Teaching & Extension')+'<section><div class="wrap"><div class="section-head"><div><p class="eyebrow">Courses with Dr. Márcio R. Nunes</p><h2>From understanding<br>to application.</h2></div><p>Course information is based on the director’s UF faculty listing. Scheduling and enrollment are confirmed through UF.</p></div><div class="course-grid"><article class="course"><p class="code">SWS5132</p><div class="icon-box">'+icon('globe')+'</div><h2>Tropical Soil Management</h2><p>Explore tropical soils and the management decisions that support productive and sustainable agriculture.</p>'+arrow('UF course information',FACULTY)+'</article><article class="course"><p class="code">SWS4207 / SWS5208</p><div class="icon-box">'+icon('leaf')+'</div><h2>Sustainable Agricultural and Urban Land Management</h2><p>Study land management in agricultural and urban settings through the lens of sustainability.</p>'+arrow('UF course information',FACULTY)+'</article></div></div></section><section class="soft"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Training &amp; practical skills</p><h2>Learn by exploring.</h2></div><p>Training topics are outlined below. Dates, formats, and participation details will be announced when confirmed.</p></div><div class="training-grid">'
for title,desc,symbol in [('Soil Laboratory Analysis','Sampling, measurements, and interpretation.','flask'),('Soil Physics','Soil structure, water, and physical processes.','waves'),('Soil Biology','Biological activity and soil functions.','leaf'),('Soil Chemistry','Chemical properties and nutrient processes.','layers')]:
 teaching+=f'<article class="training-card"><div class="icon-box">{icon(symbol)}</div><h3>{title}</h3><p>{desc}</p></article>'
teaching+='</div><p class="source-note">Training themes only; registration is not currently offered on this website.</p></div></section>'+contact_strip()
page('teaching-extension.html','Teaching and Extension',teaching)

tools=head('Tools for soil decisions.','Research translated into practical resources for soil health assessment.','Research / Tools')+'<section><div class="wrap tool-feature"><div><p class="eyebrow">Available web tool</p><h2>gSHAPE</h2><p>Soil Health Assessment Protocol and Evaluation. Explore the tool, understand its purpose, and learn how to get started.</p><div class="actions">'+arrow('Tool guide','gshape.html','button')+arrow('Launch gSHAPE',APP)+'</div></div>'+app_window()+'</div></section><section class="soft"><div class="wrap"><div class="notice"><p>Additional laboratory tools will appear here as they become available.</p></div></div></section>'
page('tools.html','Tools',tools)
gshape=head('gSHAPE','Soil Health Assessment Protocol and Evaluation — a web tool for soil health assessment in context.','Research / Tools / gSHAPE')+'<section><div class="wrap tool-feature"><div><p class="eyebrow">Why it was developed</p><h2>Make soil measurements<br>more meaningful.</h2><p>A soil measurement needs context. gSHAPE offers a browser interface for exploring evaluation frameworks and measured indicators alongside the location and inputs relevant to the selected assessment.</p><p>It brings physical, chemical, and biological indicators into one place for soil health assessment and benchmarking.</p>'+arrow('Launch gSHAPE',APP,'button')+'</div>'+app_window()+'</div></section><section class="soft"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Getting started</p><h2>How to use gSHAPE</h2></div><p>Use your measured data. Follow the tool’s field labels and units for the selected framework.</p></div><div class="steps">'
for title,desc in [('Set the location','Choose the country and complete any location fields requested by the tool.'),('Select a framework','Choose an available evaluation framework appropriate to your assessment.'),('Choose indicators','Select the soil indicators you have measured, then enter the requested values and units.'),('Review the assessment','Explore the scores and guidance shown by the tool. Interpret them within your soil and management context.')]:
 gshape+=f'<article class="step"><h3>{title}</h3><p>{desc}</p></article>'
gshape+='</div></div></section><section><div class="wrap"><div class="section-head"><div><p class="eyebrow">A look inside</p><h2>The assessment interface</h2></div><p>The live app lets you choose a location, evaluation framework, and target soil health indicators.</p></div><figure style="margin:0"><div class="screenshot"><img src="assets/gshape-interface.jpg" alt="Actual gSHAPE start screen showing the country and framework controls and physical, chemical, and biological indicator groups" width="1350" height="900" loading="lazy"></div><figcaption class="figure-note">gSHAPE start screen, captured November 17, 2026. This is an interface example, not a soil assessment result.</figcaption></figure></div></section><section class="soft"><div class="wrap tiles">'+tile('Physical indicators','Examples in the interface include bulk density, macroaggregate stability, and available water capacity.',APP,'Explore the tool','layers')+tile('Chemical indicators','Examples include pH, soil phosphorus, extractable potassium, and electrical conductivity.',APP,'Explore the tool','flask')+tile('Biological indicators','Examples include soil organic carbon, potentially mineralizable nitrogen, and microbial biomass carbon.',APP,'Explore the tool','leaf')+'</div></section>'
page('gshape.html','gSHAPE Tool Guide',gshape)

news=head('Latest News','Research highlights, publications, and announcements from our laboratory.','About / News')+'<section><div class="wrap">'+feed(True)+'</div></section>'
page('news.html','News',news)
for i,item in enumerate(NEWS):
 typ='publication' if item['category']=='Publications' else ('tool' if item['category']=='Tools' else 'media' if item['category']=='Media' else '')
 article='<section><div class="wrap"><article class="article"><p class="crumb"><a href="index.html">Home</a><span>/</span><a href="news.html">News</a></p><div class="meta"><span class="badge">'+item['category']+'</span><time datetime="'+item['date']+'">'+date_label(item['date'])+'</time></div><h1>'+E(item['title'])+'</h1><p class="article-lead">'+E(item['summary'])+'</p><div class="news-art '+typ+'">'+icon('book' if typ=='publication' else 'grid' if typ=='tool' else 'news')+'</div>'
 article+=''.join('<p>'+E(p)+'</p>' for p in item['paragraphs'])
 article+='<div class="article-source">'+arrow(item['source_label'],item['source'])+'</div><nav class="article-nav" aria-label="Article navigation">'
 if i>0:article+='<a href="news-'+NEWS[i-1]['slug']+'.html"><small>← Newer article</small>'+E(NEWS[i-1]['title'])+'</a>'
 else:article+='<span></span>'
 if i<len(NEWS)-1:article+='<a href="news-'+NEWS[i+1]['slug']+'.html"><small>Older article →</small>'+E(NEWS[i+1]['title'])+'</a>'
 else:article+='<a href="news.html">Back to all news →</a>'
 article+='</nav></article></div></section>'
 page('news-'+item['slug']+'.html',item['title'],article,desc=item['summary'])

media=head('Media &amp; stories','Public features and conversations about our director and the lab’s research.','About / Media')+'<section><div class="wrap"><div class="course-grid"><article class="tile"><div class="icon-box">'+icon('news')+'</div><p class="meta">UF/IFAS · August 27, 2022</p><h2 style="font-size:28px">Meet Márcio Nunes</h2><p>A UF/IFAS interview introduces his farming background and vision for research and teaching in tropical soils.</p>'+arrow('Read the feature',FEATURE)+'</article><article class="tile"><div class="icon-box">'+icon('globe')+'</div><h2 style="font-size:28px">More from the laboratory</h2><p>Find publications, tool features, and website announcements in our News section.</p>'+arrow('Visit News','news.html')+'</article></div><p class="source-note">Additional interviews, videos, and external media coverage will be added here.</p></div></section>'
